        ST("Francis Sinclair", two("Geology for Beginners (2 parts, chapter 2)", "Geology for Beginners (2 parties, chapitre 2)"), two("Hut northwest of Strawberry; 10 rock carvings", "Cabane au nord-ouest de Strawberry ; 10 gravures rupestres")),
