        ST("Algernon Wasp", two("Duchesses and other Animals (6 parts, chapter 4)", "Duchesses and other Animals (6 parties, chapitre 4)"), two("North of Saint Denis, Bayou Nwa; orchids, feathers and hats", "Au nord de Saint-Denis, Bayou Nwa ; orchidées, plumes et chapeaux")),
        ST(two("Henri Lemieux, with Jean-Marc Mercier", "Henri Lemieux, avec Jean-Marc Mercier"), two("Idealism and Pragmatism for Beginners (3 parts, chapter 4, after \"The Gilded Cage\")", "Idealism and Pragmatism for Beginners (3 parties, chapitre 4, après \"The Gilded Cage\")"), two("The mayor's residence, northwest Saint Denis, at night", "La résidence du maire, nord-ouest de Saint-Denis, de nuit")),
        ST(two("Sampson Black and Wendell White", "Sampson Black et Wendell White"), two("The Ties That Bind Us (4 parts, chapter 4)", "The Ties That Bind Us (4 parties, chapitre 4)"), two("Woods south of Rhodes; five wanted posters to collect in town", "Bois au sud de Rhodes ; cinq avis de recherche à récupérer en ville")),
        ST("Obediah Hinton", two("The Wisdom of the Elders (5 parts, chapter 5)", "The Wisdom of the Elders (5 parties, chapitre 5)"), two("Butcher Creek, Roanoke Ridge; Lemuel is found by a bridge nearby", "Butcher Creek, Roanoke Ridge ; Lemuel est trouvé près d'un pont voisin")),
        ST("Hamish Sinclair", two("The Veteran (4 parts, chapter 6)", "The Veteran (4 parties, chapitre 6)"), two("Grizzlies East; Veteran's Homestead and O'Creagh's Run", "Grizzlies East ; Veteran's Homestead et O'Creagh's Run")),
